/** House totals distributed into rooms[] by template weights. */
const SIMPLE_DISTRIBUTE_FIELDS = [
  "lights_onoff",
  "lights_dimmable",
  "led_strips",
  "switches",
  "shutters",
  "ufh_loops",
  "leak_sensors",
  "motion_sensors",
  "door_contacts",
  "smart_sockets",
];

