function ensureRoomsSeeded() {
  if (state.ui_mode === "simple") {
    if (!state.rooms?.length) runSimpleSync();
    else {
      state.rooms = state.rooms.map((r) => ({
        ...roomDefaults(r.template || "living"),
        ...r,
        template: r.template || "living",
        panel_id: r.panel_id || firstPanelId(),
        manual: r.manual && typeof r.manual === "object" ? r.manual : {},
      }));
    }
    return;
  }
  if (state.rooms?.length && state.rooms_user_edited) {
    state.rooms = state.rooms.map((r) => ({
      ...roomDefaults(r.template || "living"),
      ...r,
      template: r.template || "living",
      panel_id: r.panel_id || firstPanelId(),
      manual: r.manual && typeof r.manual === "object" ? r.manual : {},
    }));
    return;
  }
  state.rooms = seedRoomsFromProperty(
    state.object.property_type || "apartment",
    Number(state.object.floor_area_m2) || 0,
    Number(state.object.floors) || 1,
  ).map((r) => ({ ...r, manual: r.manual || {} }));
  state.rooms_user_edited = false;
}

/** Migrate v4/v5: cabinets → panels; ensure room.manual + simple block. */
function migrateState(saved) {
  if (!Array.isArray(saved.panels) || saved.panels.length === 0) {
    saved.panels = defaultPanels();
  }
  const mainId = saved.panels[0].id || "panel-1";
  saved.panels = saved.panels.map((p, i) => ({
    id: String(p.id || `panel-${i + 1}`),
    name: String(p.name || (i === 0 ? "Main panel" : `Panel ${i + 1}`)),
    location: String(p.location || ""),
  }));
  if (Array.isArray(saved.rooms)) {
    const panelIds = new Set(saved.panels.map((p) => p.id));
    saved.rooms = saved.rooms.map((r) => ({
      ...r,
      panel_id:
        r.panel_id && panelIds.has(r.panel_id) ? r.panel_id : mainId,
      manual: r.manual && typeof r.manual === "object" ? r.manual : {},
    }));
  }
  if (saved.systems) {
    const defaults = emptySystems(mainId);
    const panelIds = new Set(saved.panels.map((p) => p.id));
    for (const k of Object.keys(defaults)) {
      saved.systems[k] = { ...defaults[k], ...(saved.systems[k] || {}) };
      if (k === "system") continue;
      const pid = saved.systems[k].panel_id;
      if (!pid || !panelIds.has(pid)) {
        saved.systems[k].panel_id = mainId;
      }
    }
    if (saved.systems.system) {
      delete saved.systems.system.cabinets;
    }
  }
  if (!saved.simple || typeof saved.simple !== "object") {
    saved.simple = {
      counts: defaultSimpleRoomCounts(),
      totals: defaultSimpleTotals(),
      toggles: defaultSimpleToggles(),
      warnings: [],
    };
  } else {
    saved.simple = {
      counts: { ...defaultSimpleRoomCounts(), ...(saved.simple.counts || {}) },
      totals: { ...defaultSimpleTotals(), ...(saved.simple.totals || {}) },
      toggles: { ...defaultSimpleToggles(), ...(saved.simple.toggles || {}) },
      warnings: Array.isArray(saved.simple.warnings) ? saved.simple.warnings : [],
    };
  }
  if (saved.ui_mode !== "advanced") saved.ui_mode = "simple";
  return saved;
}

function loadState() {
  try {
    let raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) raw = localStorage.getItem("hm_configurator_v5");
    if (!raw) raw = localStorage.getItem("hm_configurator_v4");
    if (!raw) {
      try {
        const mode = localStorage.getItem(MODE_KEY);
        if (mode === "advanced" || mode === "simple") state.ui_mode = mode;
      } catch {
        /* ignore */
      }
      return;
    }
    const saved = migrateState(JSON.parse(raw));
    if (saved.rulesVersion && rules && saved.rulesVersion !== rules.version) return;
    Object.assign(state, saved, { rulesVersion: rules?.version });
    if (!state.panels?.length) state.panels = defaultPanels();
    if (!state.systems) state.systems = emptySystems(firstPanelId());
    const defaults = emptySystems(firstPanelId());
    state.systems = { ...defaults, ...state.systems };
    for (const k of Object.keys(defaults)) {
      state.systems[k] = { ...defaults[k], ...(saved.systems?.[k] || {}) };
      if (k !== "system" && !state.systems[k].panel_id) {
        state.systems[k].panel_id = firstPanelId();
      }
    }
    delete state.systems.system?.cabinets;
    if (!state.simple) {
      state.simple = {
        counts: defaultSimpleRoomCounts(),
        totals: defaultSimpleTotals(),
        toggles: defaultSimpleToggles(),
        warnings: [],
      };
    }
    if (state.ui_mode !== "advanced") state.ui_mode = "simple";
  } catch {
    /* ignore */
  }
}

function markRoomFieldManual(room, key) {
  if (!room.manual || typeof room.manual !== "object") room.manual = {};
  if (SIMPLE_DISTRIBUTE_FIELDS.includes(key) || key === "lights_dimmable") {
    room.manual[key] = true;
  }
}

function runSimpleSync({ rebuildCounts = false } = {}) {
  if (rebuildCounts) {
    /* keep state.simple.counts as set by sliders */
  }
  const { rooms, warnings } = applySimpleDistribution({
    counts: state.simple.counts,
    totals: state.simple.totals,
    rooms: state.rooms,
    roomTypeLabels: rules?.room_type_labels,
    roomTemplates: rules?.room_templates,
    roomDefaultsFn: (t) => roomDefaults(t),
    panelId: firstPanelId(),
  });
  state.rooms = rooms;
  state.rooms_user_edited = true;
  state.simple.warnings = warnings;
  state.systems = applySimpleToggles(state.systems, state.simple.toggles);
  // Mirror UFH house total from slider for Systems collector field.
  state.systems.heating.collector_loops = Math.max(
    0,
    Number(state.simple.totals.ufh_loops) || 0,
  );
}

function syncSimpleSlidersFromRooms() {
  state.simple.totals = totalsFromRooms(state.rooms);
  state.simple.counts = countsFromRooms(state.rooms);
  state.simple.toggles = togglesFromSystems(state.systems);
  state.simple.warnings = [];
}

function applyPreset(kind) {
  const p = simplePreset(kind === "villa" ? "villa" : kind === "house" ? "house" : "apartment");
  state.object.property_type = p.property_type;
  state.object.floor_area_m2 = p.floor_area_m2;
  state.object.floors = p.floors;
  state.simple.counts = p.counts;
  state.simple.totals = p.totals;
  state.simple.toggles = p.toggles;
  state.rooms = [];
  runSimpleSync();
}

function saveState() {
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ ...state, rulesVersion: rules?.version }),
    );
  } catch {
    /* ignore */
  }
}

function buildInputs() {
  // Simple mode always uses one panel; Advanced keeps user-created panels.
  const panels =
    state.ui_mode === "simple"
      ? [{ id: "panel-1", name: "Main panel", location: "" }]
      : resolvePanels({ panels: state.panels });
  const mainId = panels[0]?.id || "panel-1";
  if (state.expert) {
    return {
      panels,
      mode: "expert",
      expert: { demand: { ...state.expertDemand } },
      stage: state.object.stage,
      systems: {
        system: { ...state.systems.system },
      },
    };
  }
  const systems = JSON.parse(JSON.stringify(state.systems));
  if (state.ui_mode === "simple") {
    for (const sec of [
      "heating",
      "ventilation",
      "water",
      "electrical",
      "security",
      "lighting_scenes",
    ]) {
      if (systems[sec] && typeof systems[sec] === "object") {
        systems[sec].panel_id = mainId;
      }
    }
  }
  return {
    panels,
    property_type: state.object.property_type,
    floor_area_m2: state.object.floor_area_m2,
    floors: state.object.floors,
    stage: state.object.stage,
    name: state.object.name,
    rooms: state.rooms.map((r) => ({
      ...r,
      panel_id:
        state.ui_mode === "simple" ? mainId : r.panel_id || mainId,
    })),
    systems,
  };
}

function runEstimate(inputs, prices = priceMap) {
  if (!rules) throw new Error("Rules not loaded");
  return estimate(inputs, rules, prices);
}

async function refreshPrices(result) {
  const fromPanels = (result.panels || []).flatMap((p) => p.modules || []);
  const mods = fromPanels.length ? fromPanels : result.modules || [];
  const urls = mods.map((m) => m.shop_url).filter(Boolean);
  if (!urls.length) return;
  const map = await fetchPrices(urls, { preferredCurrency: detectShopCurrency() });
  priceMap = toEstimatePriceMap(map);
}

function formatPrice(p) {
  if (!p || typeof p.amount !== "number" || !Number.isFinite(p.amount)) {
    return '<span class="hm-muted">price unavailable</span>';
  }
  const amb = p.currencyAmbiguous
    ? ' <span class="hm-muted">(currency may not match shop session)</span>'
    : "";
  return `${p.amount} ${p.currency || ""}${amb}`;
}

function enclosureMessage(enclosure, { compact = false } = {}) {
  if (!enclosure) return `<p>Enclosure: —</p>`;
  if (enclosure.status === "blocked") {
    if (enclosure.reason === "din_units_missing") {
      const mods = (enclosure.modules || []).join(", ");
      return `<p class="hm-warn">Panel layout: blocked — DIN width unknown for ${mods || "some HomeMaster modules"}</p>`;
    }
    return `<p class="hm-warn">Panel layout: blocked — ${enclosure.reason}</p>`;
  }
  if (enclosure.status === "overflow" || enclosure.overflow) {
    return `<p class="hm-warn">Enclosure: ${enclosure.din_needed} M needed exceeds max ${enclosure.max_sections || 4}×(6×24)=${(enclosure.max_sections || 4) * (enclosure.max_capacity || 144)} M — add another panel on screen 1 or reduce demand.</p>`;
  }
  const occupied = enclosure.occupied ?? enclosure.din_occupied ?? enclosure.din_total;
  const reserve = enclosure.reserve ?? enclosure.din_reserve;
  const free = enclosure.free ?? enclosure.din_free;
  const breakdown =
    occupied != null && reserve != null && free != null
      ? `occupied ${occupied} M · reserve ${reserve} M (${enclosure.reserve_pct}%) · needed ${enclosure.din_needed} M · free after rounding ${free} M`
      : `${enclosure.din_total} M used → ${enclosure.din_needed} M with reserve`;
  if (compact || enclosure.panels > 1) {
    return `<p>DIN (${enclosure.panels > 1 ? "all panels" : "panel"}): ${breakdown} → capacity ${enclosure.capacity} M</p>`;
  }
  const cabinets = enclosure.cabinets || 1;
  const each = enclosure.capacity_each ?? enclosure.capacity;
  const layout =
    cabinets > 1
      ? `${cabinets} × (${enclosure.rows} rows × ${enclosure.row_width})`
      : `${enclosure.rows} rows × ${enclosure.row_width}`;
  const mm =
    enclosure.width_mm != null && enclosure.height_mm != null
      ? `, approx. ${enclosure.width_mm} × ${enclosure.height_mm} mm`
      : "";
  const coupled = cabinets > 1 ? " — coupled sections" : "";
  const blank =
    enclosure.blanking_qty > 0
      ? ` · ${enclosure.blanking_qty} blanking plate(s)`
      : "";
  return `<p>Enclosure: ${breakdown} → ${cabinets > 1 ? `${cabinets}×` : "1×"} enclosure ${each} M (${layout}${mm})${coupled}${blank}</p>`;
}

function channelUsageTable(usage) {
  const rows = (usage || []).filter((r) => r.needed > 0 || r.reserve);
  if (!rows.length) return "";
  const body = rows
    .map((r) => {
      const tip = r.note
        ? ` title="${escapeAttr(r.note)}"`
        : "";
      const note = r.note
        ? `<div class="hm-muted" style="font-size:0.85em;max-width:28rem">${escapeAttr(r.note)}</div>`
        : "";
      return `<tr${tip}><td>${escapeAttr(r.label)}${note}</td><td>${r.needed}</td><td>${r.supplied}</td><td>${r.spare}</td></tr>`;
    })
    .join("");
  return `
    <h3 class="hm-channel-heading">Channel usage</h3>
    <table class="hm-table hm-channel-table">
      <thead><tr><th>Channel type</th><th>Needed</th><th>Supplied</th><th>Spare</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
}

function el(html) {
  const t = document.createElement("template");
  t.innerHTML = html.trim();
  return t.content.firstElementChild;
}

function escapeAttr(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;");
}

/**
 * @param {HTMLElement} root
 */
function mountConfigurator(root) {
  root.innerHTML = "";
  const shell = el(`
    <div class="hm-estimator">
      <header class="hm-estimator__header">
        <h1>How much does a HomeMaster system cost?</h1>
        <p class="hm-estimator__tagline">Get an instant estimate for your home</p>
        <div class="hm-mode-toggle" role="group" aria-label="Configurator mode">
          <button type="button" id="hm-mode-simple" class="hm-mode-btn">Simple</button>
          <button type="button" id="hm-mode-advanced" class="hm-mode-btn">Advanced</button>
        </div>
        <label class="hm-expert" id="hm-expert-wrap"><input type="checkbox" id="hm-expert"> Expert mode (direct demand)</label>
      </header>
      <div class="hm-examples" id="hm-examples"></div>
      <nav class="hm-steps" id="hm-steps"></nav>
      <div class="hm-layout" id="hm-layout">
        <main class="hm-main" id="hm-main"></main>
        <aside class="hm-summary" id="hm-summary"></aside>
      </div>
    </div>
  `);
  root.appendChild(shell);

  const stepsNav = shell.querySelector("#hm-steps");
  const main = shell.querySelector("#hm-main");
  const summary = shell.querySelector("#hm-summary");
  const layout = shell.querySelector("#hm-layout");
  const examplesEl = shell.querySelector("#hm-examples");
  const expertCb = shell.querySelector("#hm-expert");
  const expertWrap = shell.querySelector("#hm-expert-wrap");
  const modeSimpleBtn = shell.querySelector("#hm-mode-simple");
  const modeAdvancedBtn = shell.querySelector("#hm-mode-advanced");

  function setUiMode(mode, { syncFromRooms = false } = {}) {
    const next = mode === "advanced" ? "advanced" : "simple";
    if (next === "simple" && state.ui_mode === "advanced") {
      syncSimpleSlidersFromRooms();
    }
    // Simple → Advanced: do not redistribute.
    state.ui_mode = next;
    try {
      localStorage.setItem(MODE_KEY, next);
    } catch {
      /* ignore */
    }
    if (syncFromRooms) syncSimpleSlidersFromRooms();
    saveState();
    render();
  }

  modeSimpleBtn.addEventListener("click", () => setUiMode("simple"));
  modeAdvancedBtn.addEventListener("click", () => setUiMode("advanced"));

  expertCb.checked = !!state.expert;
  expertCb.addEventListener("change", () => {
    state.expert = expertCb.checked;
    saveState();
    render();
  });

  function renderModeChrome() {
    const simple = state.ui_mode === "simple";
    modeSimpleBtn.classList.toggle("is-active", simple);
    modeAdvancedBtn.classList.toggle("is-active", !simple);
    stepsNav.hidden = simple || !!state.expert;
    expertWrap.hidden = simple;
    layout.classList.toggle("hm-layout--simple", simple);
    examplesEl.hidden = !simple;
  }

  function renderExamples() {
    if (state.ui_mode !== "simple") {
      examplesEl.innerHTML = "";
      return;
    }
    const cards = [
      ["apartment", "Apartment", "apartment"],
      ["house", "Detached house", "house"],
      ["villa", "Large villa", "villa"],
    ];
    examplesEl.innerHTML = `
      <p class="hm-examples__label">Start from an example</p>
      <div class="hm-examples__row">
        ${cards
          .map(
            ([id, label, icon]) =>
              `<button type="button" class="hm-example-card" data-preset="${id}">
                <span class="hm-example-card__ico">${hmIcon(icon, 22)}</span>
                <span class="hm-example-card__text">
                  <strong>${label}</strong>
                  <span class="hm-example-price" data-preset-price="${id}">…</span>
                </span>
              </button>`,
          )
          .join("")}
      </div>`;
    examplesEl.querySelectorAll("[data-preset]").forEach((btn) => {
      btn.onclick = () => {
        applyPreset(btn.dataset.preset);
        saveState();
        render();
        refreshExamplePrices();
      };
    });
    refreshExamplePrices();
  }

  async function refreshExamplePrices() {
    if (state.ui_mode !== "simple") return;
    const saved = structuredClone({
      object: state.object,
      rooms: state.rooms,
      systems: state.systems,
      simple: state.simple,
    });
    for (const kind of ["apartment", "house", "villa"]) {
      const elPrice = examplesEl.querySelector(`[data-preset-price="${kind}"]`);
      if (!elPrice) continue;
      try {
        const p = simplePreset(kind);
        const { rooms } = applySimpleDistribution({
          counts: p.counts,
          totals: p.totals,
          rooms: [],
          roomTypeLabels: rules?.room_type_labels,
          roomTemplates: rules?.room_templates,
          roomDefaultsFn: (t) => roomDefaults(t),
          panelId: firstPanelId(),
        });
        const systems = applySimpleToggles(emptySystems(firstPanelId()), p.toggles);
        systems.heating.collector_loops = p.totals.ufh_loops || 0;
        const inputs = {
          panels: resolvePanels({ panels: state.panels }),
          rooms,
          systems,
          stage: state.object.stage,
          property_type: p.property_type,
          floor_area_m2: p.floor_area_m2,
          floors: p.floors,
        };
        let result = estimate(inputs, rules, priceMap);
        const urls = (result.modules || []).map((m) => m.shop_url).filter(Boolean);
        if (urls.length && Object.keys(priceMap).length === 0) {
          const map = await fetchPrices(urls, { preferredCurrency: detectShopCurrency() });
          priceMap = toEstimatePriceMap(map);
          result = estimate(inputs, rules, priceMap);
        }
        const tot = cartTotal(result, priceMap);
        elPrice.textContent =
          tot && typeof tot.total === "number"
            ? `from ${tot.total} ${tot.currency}`
            : "see estimate";
      } catch {
        elPrice.textContent = "—";
      }
    }
    // Restore live state (presets must not clobber).
    state.object = saved.object;
    state.rooms = saved.rooms;
    state.systems = saved.systems;
    state.simple = saved.simple;
  }

  function renderSteps() {
    if (state.ui_mode === "simple") {
      stepsNav.innerHTML = "";
      return;
    }
    stepsNav.innerHTML = STEPS.map(
      (name, i) =>
        `<button type="button" class="hm-step ${i === state.step ? "is-active" : ""}" data-step="${i}">${i + 1}. ${name}</button>`,
    ).join("");
    stepsNav.querySelectorAll(".hm-step").forEach((btn) => {
      btn.addEventListener("click", () => {
        state.step = Number(btn.dataset.step);
        saveState();
        render();
      });
    });
  }

  function liveResult() {
    try {
      return runEstimate(buildInputs(), priceMap);
    } catch (err) {
      return { error: String(err) };
    }
  }

  function renderSummary(result) {
    if (result.error) {
      summary.innerHTML = `<p class="hm-warn">${result.error}</p>`;
      return;
    }
    const mods = (result.modules || [])
      .map((m) => {
        const p = priceMap[m.sku];
        return `<li><strong>${m.qty}×</strong> ${m.id}<br><span class="hm-muted">${formatPrice(p)}</span></li>`;
      })
      .join("");
    const tot = cartTotal(result, priceMap);
    let totalLine = "HomeMaster subtotal: —";
    if (tot && typeof tot.total === "number") {
      const amb = tot.currencyAmbiguous
        ? ' <span class="hm-muted">(currency may not match shop session)</span>'
        : "";
      totalLine = `HomeMaster subtotal: ${tot.total} ${tot.currency} (incl. VAT)${amb}`;
    }
    const warns = (result.assumptions || [])
      .filter((a) => /ALM 12 V rail:.*exceeds/i.test(a))
      .map((a) => `<p class="hm-warn">${escapeAttr(a)}</p>`)
      .join("");
    const split = result.split_warning
      ? `<p class="hm-warn">${escapeAttr(result.split_warning)}</p>`
      : "";
    const segs =
      result.topology?.segment_count ?? result.topology?.segments?.length ?? 0;
    const ctrlList = result.topology?.controllers;
    const ctrlCount = Array.isArray(ctrlList)
      ? ctrlList.length
      : (result.modules || [])
          .filter((m) => rules.modules?.[m.id]?.master)
          .reduce((s, m) => s + (m.qty || 0), 0);
    const ctrlDetail =
      Array.isArray(ctrlList) && ctrlList.length
        ? ` (${ctrlList.map((c) => `${c.id}→seg ${c.segment}`).join(", ")})`
        : "";
    summary.innerHTML = `
      <h2>Summary</h2>
      ${channelUsageTable(result.channel_usage)}
      <ul class="hm-modlist">${mods || "<li>—</li>"}</ul>
      <p>Panels: ${result.panel_count ?? state.panels.length}</p>
      <p>RS-485 segments: ${segs} · controllers: ${ctrlCount}${ctrlDetail}</p>
      <p>24 V power: ${result.power?.total_w ?? "—"} W</p>
      ${enclosureMessage(result.enclosure, { compact: true })}
      ${split}
      ${warns}
      <p class="hm-total">${totalLine}</p>
    `;
  }

  function reseedRooms(force) {
    if (!force && state.rooms_user_edited) return;
    state.rooms = seedRoomsFromProperty(
      state.object.property_type,
      Number(state.object.floor_area_m2) || 0,
      Number(state.object.floors) || 1,
    );
    state.rooms_user_edited = false;
    state.rooms_expanded = 0;
  }

  function renderObject() {
    const o = state.object;
    const s = state.systems.system;
    if (state.panels_expanded == null || state.panels_expanded >= state.panels.length) {
      state.panels_expanded = 0;
    }
    main.innerHTML = `
      <h2>Property</h2>
      <label>Project name <input id="f-name" value="${escapeAttr(o.name || "")}"></label>
      <label>Property type
        <select id="f-ptype">${PROPERTY_TYPES.map(
          ([v, lab]) =>
            `<option value="${v}" ${v === o.property_type ? "selected" : ""}>${lab}</option>`,
        ).join("")}</select>
      </label>
      <label>Floor area m² <input id="f-area" type="number" min="0" value="${o.floor_area_m2 ?? 60}"></label>
      <label>Number of floors <input id="f-floors" type="number" min="1" value="${o.floors || 1}"></label>
      <label>Project stage
        <select id="f-stage">${STAGES.map(
          ([v, lab]) =>
            `<option value="${v}" ${v === o.stage ? "selected" : ""}>${lab}</option>`,
        ).join("")}</select>
      </label>
      <p class="hm-muted">Property type and floor area choose a room template and pre-fill the Rooms step. Stage goes to the quote only — it does not change the module list.</p>

      <h3>Panels</h3>
      <p class="hm-muted">Each panel is calculated independently — its own controller, bus, PSU and enclosure.</p>
      <div id="panel-notice" class="hm-room-undo" ${state.panel_migrate_notice ? "" : "hidden"}>${
        state.panel_migrate_notice
          ? `<span>${escapeAttr(state.panel_migrate_notice)}</span>`
          : ""
      }</div>
      <div id="panel-list"></div>
      <button type="button" id="add-panel">+ panel</button>

      <details class="hm-sys-section" open>
        <summary>System</summary>
        <div class="hm-sys-grid">
          <div class="hm-room-field">
            <div class="hm-room-field__label"><span>Channel reserve</span></div>
            <input id="f-reserve" type="range" min="0" max="30" value="${s.reserve_pct ?? 15}">
            <span id="reserve-val">${s.reserve_pct ?? 15}%</span>
          </div>
          <div class="hm-room-field">
            <div class="hm-room-field__label"><span>Manual controls on modules</span></div>
            <select id="f-manual">
              <option value="yes" ${s.manual_control !== false ? "selected" : ""}>Yes</option>
              <option value="no" ${s.manual_control === false ? "selected" : ""}>No</option>
            </select>
          </div>
          <div class="hm-room-field">
            <div class="hm-room-field__label"><span>Home Assistant server</span></div>
            <select id="f-ha">
              <option value="needed" ${s.ha_server === "needed" ? "selected" : ""}>Needed</option>
              <option value="own" ${s.ha_server === "own" ? "selected" : ""}>Have my own</option>
            </select>
          </div>
        </div>
      </details>
      <div class="hm-actions"><button type="button" id="hm-next">Next</button></div>
    `;

    const panelList = main.querySelector("#panel-list");
    function paintPanels() {
      panelList.innerHTML = state.panels
        .map((p, i) => {
          const open = i === state.panels_expanded;
          if (!open) {
            const loc = p.location ? ` · ${p.location}` : "";
            return `<button type="button" class="hm-room-collapsed" data-pexpand="${i}">
              <span class="hm-room-icon">Panel</span>
              <span class="hm-room-collapsed__text"><strong>${escapeAttr(p.name)}</strong>
                <span class="hm-muted">${escapeAttr(loc)}</span></span>
              <span class="hm-room-chevron">▾</span>
            </button>`;
          }
          const canDelete = state.panels.length > 1;
          return `<article class="hm-room-card hm-room-card--open" data-pi="${i}">
            <header class="hm-room-card__toolbar">
              <button type="button" class="hm-room-collapse" data-pcollapse="${i}" aria-label="Collapse">▴</button>
              <h3 class="hm-room-card__title">${escapeAttr(p.name || "Panel")}</h3>
              ${
                canDelete
                  ? `<button type="button" class="hm-room-delete" data-prm="${i}">
                <svg class="hm-room-delete__icon" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M3 6h18M8 6V4h8v2M9 10v8M12 10v8M15 10v8M6 6l1 14h10l1-14"/>
                </svg>
                Delete panel
              </button>`
                  : ""
              }
            </header>
            <div class="hm-room-card__identity">
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Name</span></div>
                <input data-pk="name" value="${escapeAttr(p.name || "")}" placeholder="e.g. Floor 1">
              </div>
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Location <span class="hm-muted">(optional)</span></span></div>
                <input data-pk="location" value="${escapeAttr(p.location || "")}" placeholder="e.g. Utility room">
              </div>
            </div>
          </article>`;
        })
        .join("");

      panelList.querySelectorAll("[data-pexpand]").forEach((btn) => {
        btn.onclick = () => {
          state.panels_expanded = Number(btn.dataset.pexpand);
          saveState();
          paintPanels();
        };
      });
      panelList.querySelectorAll("[data-pcollapse]").forEach((btn) => {
        btn.onclick = () => {
          state.panels_expanded = -1;
          saveState();
          paintPanels();
        };
      });
      panelList.querySelectorAll(".hm-room-card").forEach((card) => {
        const i = Number(card.dataset.pi);
        card.querySelectorAll("[data-pk]").forEach((inp) => {
          const apply = () => {
            const k = inp.dataset.pk;
            state.panels[i][k] = inp.value;
            if (k === "name") {
              const t = card.querySelector(".hm-room-card__title");
              if (t) t.textContent = inp.value.trim() || "Panel";
            }
            saveState();
            bump();
          };
          inp.oninput = inp.onchange = apply;
        });
        const rm = card.querySelector("[data-prm]");
        if (rm) {
          rm.onclick = () => {
            if (state.panels.length <= 1) return;
            const removed = state.panels[i];
            const fallback = state.panels[i === 0 ? 1 : 0].id;
            state.panels.splice(i, 1);
            let moved = 0;
            for (const room of state.rooms) {
              if (room.panel_id === removed.id) {
                room.panel_id = fallback;
                moved += 1;
              }
            }
            for (const sec of SYSTEM_SECTIONS) {
              if (state.systems[sec.id]?.panel_id === removed.id) {
                state.systems[sec.id].panel_id = fallback;
              }
            }
            if (state.panels_expanded >= state.panels.length) {
              state.panels_expanded = state.panels.length - 1;
            }
            state.panel_migrate_notice =
              moved > 0
                ? `${moved} room(s) from “${removed.name}” moved to “${panelById(fallback).name}”.`
                : "";
            saveState();
            renderObject();
            bump();
          };
        }
      });
    }
    paintPanels();

    main.querySelector("#add-panel").onclick = () => {
      const n = state.panels.length + 1;
      state.panels.push({
        id: `panel-${Date.now().toString(36)}`,
        name: `Panel ${n}`,
        location: "",
      });
      state.panels_expanded = state.panels.length - 1;
      state.panel_migrate_notice = "";
      saveState();
      paintPanels();
      bump();
    };

    const reserve = main.querySelector("#f-reserve");
    const reserveVal = main.querySelector("#reserve-val");
    reserve.oninput = reserve.onchange = () => {
      state.systems.system.reserve_pct = Number(reserve.value) || 0;
      reserveVal.textContent = `${state.systems.system.reserve_pct}%`;
      saveState();
      bump();
    };
    main.querySelector("#f-manual").onchange = (e) => {
      state.systems.system.manual_control = e.target.value === "yes";
      saveState();
      bump();
    };
    main.querySelector("#f-ha").onchange = (e) => {
      state.systems.system.ha_server = e.target.value;
      saveState();
      bump();
    };
    const bumpProperty = () => {
      reseedRooms(false);
      saveState();
      bump();
    };
    main.querySelector("#f-name").oninput = (e) => {
      state.object.name = e.target.value;
      saveState();
    };
    main.querySelector("#f-ptype").onchange = (e) => {
      state.object.property_type = e.target.value;
      reseedRooms(true);
      saveState();
      bump();
    };
    main.querySelector("#f-area").oninput = (e) => {
      state.object.floor_area_m2 = Number(e.target.value) || 0;
      bumpProperty();
    };
    main.querySelector("#f-floors").oninput = (e) => {
      state.object.floors = Math.max(1, Number(e.target.value) || 1);
      bumpProperty();
    };
    main.querySelector("#f-stage").onchange = (e) => {
      state.object.stage = e.target.value;
      saveState();
    };
    main.querySelector("#hm-next").onclick = () => {
      if (!state.rooms_user_edited) reseedRooms(true);
      state.step = state.expert ? 3 : 1;
      saveState();
      render();
    };
  }

  function fieldControl(room, key, kind) {
    if (kind === "channels") {
      const v = room.led_strip_channels || 4;
      return `<select data-k="${key}">${[3, 4, 5]
        .map((n) => `<option value="${n}" ${n === v ? "selected" : ""}>${n} channels</option>`)
        .join("")}</select>`;
    }
    if (kind === "temp") {
      const v = room.temp_sensor || "none";
      return `<select data-k="${key}">${TEMP_OPTIONS.map(
        ([val, lab]) => `<option value="${val}" ${val === v ? "selected" : ""}>${lab}</option>`,
      ).join("")}</select>`;
    }
    return `<input data-k="${key}" type="number" min="0" value="${Number(room[key]) || 0}">`;
  }

  function roomFieldHtml(room, field) {
    if (!roomFieldVisible(room, field)) return "";
    const [k, label, kind, opts] = field;
    const tip = opts?.tip
      ? `<button type="button" class="hm-field-tip" title="${escapeAttr(opts.tip)}" aria-label="${escapeAttr(opts.tip)}">?</button>`
      : "";
    return `<div class="hm-room-field">
      <div class="hm-room-field__label"><span>${escapeAttr(label)}</span>${tip}</div>
      ${fieldControl(room, k, kind)}
    </div>`;
  }

  function renderRooms() {
    const templates = Object.keys(rules.room_templates || {});
    if (state.rooms_expanded == null || state.rooms_expanded >= state.rooms.length) {
      state.rooms_expanded = Math.max(0, state.rooms.length - 1);
    }
    /** @type {{ room: object, index: number, timer: ReturnType<typeof setTimeout> } | null} */
    let undoDelete = null;

    main.innerHTML = `
      <h2>Rooms</h2>
      <p class="hm-muted">Pre-filled from the property on step 1 — each room keeps the type from that template. Rooms without a name are drafts and are ignored. When you rename a room by hand, type is not inferred from the name; pick Type yourself.</p>
      <div id="room-undo" class="hm-room-undo" hidden></div>
      <div id="room-list"></div>
      <button type="button" id="add-room">+ room</button>
      <button type="button" id="reset-rooms">Reset rooms from property</button>
      <div class="hm-actions">
        <button type="button" id="hm-back">Back</button>
        <button type="button" id="hm-next">Next</button>
      </div>
    `;
    const list = main.querySelector("#room-list");
    const undoBar = main.querySelector("#room-undo");

    function clearUndo() {
      if (undoDelete?.timer) clearTimeout(undoDelete.timer);
      undoDelete = null;
      undoBar.hidden = true;
      undoBar.innerHTML = "";
    }

    function showUndo(room, index) {
      if (undoDelete?.timer) clearTimeout(undoDelete.timer);
      undoDelete = {
        room,
        index,
        timer: setTimeout(() => {
          undoDelete = null;
          undoBar.hidden = true;
          undoBar.innerHTML = "";
        }, 5000),
      };
      const label = room.name?.trim() || "Untitled room";
      undoBar.hidden = false;
      undoBar.innerHTML = `
        <span>Deleted <strong>${escapeAttr(label)}</strong>.</span>
        <button type="button" id="hm-undo-delete">Undo</button>`;
      undoBar.querySelector("#hm-undo-delete").onclick = () => {
        if (!undoDelete) return;
        const { room: restored, index: at } = undoDelete;
        clearUndo();
        state.rooms_user_edited = true;
        const insertAt = Math.min(Math.max(0, at), state.rooms.length);
        state.rooms.splice(insertAt, 0, restored);
        state.rooms_expanded = insertAt;
        saveState();
        paintRooms();
        bump();
      };
    }

    function paintRooms() {
      if (state.rooms_expanded >= state.rooms.length) {
        state.rooms_expanded = Math.max(0, state.rooms.length - 1);
      }
      list.innerHTML = state.rooms
        .map((r, i) => {
          const template =
            r.template && rules.room_templates?.[r.template] ? r.template : "living";
          if (r.template !== template) r.template = template;
          const expanded = i === state.rooms_expanded;
          const summary = roomSummaryBits(r);
          const summaryText = summary || "no equipment set";
          const title = r.name?.trim() || "Untitled room";
          const roomPanelId = r.panel_id || firstPanelId();
          const roomPanelName = panelById(roomPanelId)?.name || "Main panel";
          if (!expanded) {
            return `
            <button type="button" class="hm-room-collapsed" data-expand="${i}">
              <span class="hm-room-icon" aria-hidden="true">${roomTypeIcon(template)}</span>
              <span class="hm-room-collapsed__text">
                <strong>${escapeAttr(title)}</strong>
                <span class="hm-muted"> · ${escapeAttr(roomPanelName)}${summaryText ? ` · ${escapeAttr(summaryText)}` : ""}</span>
              </span>
              <span class="hm-room-chevron" aria-hidden="true">▾</span>
            </button>`;
          }
          const typeOpts = templates
            .map(
              (t) =>
                `<option value="${t}" ${t === template ? "selected" : ""}>${roomTypeLabel(t)}</option>`,
            )
            .join("");
          const mainFields = ROOM_FIELDS_MAIN.map((f) => roomFieldHtml(r, f)).join("");
          const moreFields = ROOM_FIELDS_MORE.map((f) => roomFieldHtml(r, f)).join("");
          return `
          <article class="hm-room-card hm-room-card--open" data-i="${i}">
            <header class="hm-room-card__toolbar">
              <button type="button" class="hm-room-collapse" data-collapse="${i}" aria-label="Collapse room">▴</button>
              <h3 class="hm-room-card__title">${escapeAttr(title)}</h3>
              <button type="button" class="hm-room-delete" data-rm="${i}">
                <svg class="hm-room-delete__icon" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M3 6h18M8 6V4h8v2M9 10v8M12 10v8M15 10v8M6 6l1 14h10l1-14"/>
                </svg>
                Delete room
              </button>
            </header>
            <div class="hm-room-card__identity hm-room-card__identity--3">
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Name</span></div>
                <input data-k="name" value="${escapeAttr(r.name || "")}" placeholder="Room name">
              </div>
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Type</span></div>
                <select data-k="template">${typeOpts}</select>
              </div>
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Panel</span></div>
                ${panelSelectHtml(roomPanelId, 'data-k="panel_id"')}
              </div>
            </div>
            <div class="hm-room-card__grid">${mainFields}</div>
            <details class="hm-room-more"><summary>More</summary>
              <div class="hm-room-card__grid">${moreFields}</div>
            </details>
          </article>`;
        })
        .join("");

      list.querySelectorAll("[data-expand]").forEach((btn) => {
        btn.onclick = () => {
          state.rooms_expanded = Number(btn.dataset.expand);
          saveState();
          paintRooms();
        };
      });
      list.querySelectorAll("[data-collapse]").forEach((btn) => {
        btn.onclick = () => {
          state.rooms_expanded = -1;
          saveState();
          paintRooms();
        };
      });

      list.querySelectorAll(".hm-room-card").forEach((card) => {
        const i = Number(card.dataset.i);
        card.querySelectorAll("[data-k]").forEach((inp) => {
          const apply = (opts = {}) => {
            state.rooms_user_edited = true;
            const key = inp.dataset.k;
            if (key === "template") {
              const name = state.rooms[i].name;
              const next = inp.value;
              const prevManual = state.rooms[i].manual || {};
              const prevPanel = state.rooms[i].panel_id;
              state.rooms[i] = {
                ...roomDefaults(next),
                name,
                template: next,
                panel_id: prevPanel || firstPanelId(),
                manual: prevManual,
              };
              saveState();
              paintRooms();
              bump();
              return;
            }
            if (key === "name") {
              state.rooms[i].name = inp.value;
              const titleEl = card.querySelector(".hm-room-card__title");
              if (titleEl) {
                titleEl.textContent = inp.value.trim() || "Untitled room";
              }
            } else if (key === "panel_id") {
              state.rooms[i].panel_id = inp.value;
            } else if (key === "temp_sensor") state.rooms[i].temp_sensor = inp.value;
            else if (key === "led_strip_channels")
              state.rooms[i].led_strip_channels = Number(inp.value) || 4;
            else {
              state.rooms[i][key] = Number(inp.value) || 0;
              markRoomFieldManual(state.rooms[i], key);
              if (key === "lights_onoff" || key === "lights_dimmable") {
                const lights = Number(state.rooms[i].lights_onoff) || 0;
                if ((Number(state.rooms[i].lights_dimmable) || 0) > lights) {
                  state.rooms[i].lights_dimmable = lights;
                }
              }
            }
            saveState();
            // After blur/change on a parent count, refresh dependent field visibility.
            if (
              opts.commit &&
              (key === "lights_onoff" || key === "led_strips")
            ) {
              paintRooms();
            }
            bump();
          };
          inp.onchange = () => apply({ commit: true });
          if (inp.tagName !== "SELECT") inp.oninput = () => apply({ commit: false });
        });
        const rm = card.querySelector("[data-rm]");
        if (rm) {
          rm.onclick = () => {
            state.rooms_user_edited = true;
            const [removed] = state.rooms.splice(i, 1);
            if (state.rooms_expanded === i) state.rooms_expanded = -1;
            else if (state.rooms_expanded > i) state.rooms_expanded -= 1;
            saveState();
            showUndo(removed, i);
            paintRooms();
            bump();
          };
        }
      });
    }

    paintRooms();
    main.querySelector("#add-room").onclick = () => {
      clearUndo();
      state.rooms_user_edited = true;
      state.rooms.push({
        ...roomDefaults("living"),
        template: "living",
        panel_id: firstPanelId(),
      });
      state.rooms_expanded = state.rooms.length - 1;
      saveState();
      paintRooms();
      bump();
    };
    main.querySelector("#reset-rooms").onclick = () => {
      clearUndo();
      reseedRooms(true);
      saveState();
      paintRooms();
      bump();
    };
    main.querySelector("#hm-back").onclick = () => {
      clearUndo();
      state.step = 0;
      saveState();
      render();
    };
    main.querySelector("#hm-next").onclick = () => {
      clearUndo();
      state.step = 2;
      saveState();
      render();
    };
  }

  function sysFieldControl(sectionId, key, kind, value) {
    if (kind === "boiler") {
      return `<select data-sys="${sectionId}.${key}">
        <option value="none" ${value === "none" ? "selected" : ""}>None</option>
        <option value="opentherm" ${value === "opentherm" ? "selected" : ""}>OpenTherm</option>
        <option value="relay" ${value === "relay" ? "selected" : ""}>Relay</option>
      </select>`;
    }
    if (kind === "powered_sensors") return ""; // custom block
    return `<input data-sys="${sectionId}.${key}" type="number" min="0" value="${Number(value) || 0}">`;
  }

  function renderPoweredSensors(container) {
    const types = rules.alarm_sensor_types || {};
    const rows = state.systems.security.powered_sensors || [];
    container.innerHTML = `
      <div class="hm-sensor-list">
        ${rows
          .map(
            (row, i) => `
          <div class="hm-sensor-row" data-si="${i}">
            <select data-sk="type">${Object.entries(types)
              .map(
                ([k, v]) =>
                  `<option value="${k}" ${k === row.type ? "selected" : ""}>${v.label || k}</option>`,
              )
              .join("")}</select>
            <input data-sk="qty" type="number" min="0" value="${row.qty || 0}">
            <button type="button" data-srm="${i}">×</button>
          </div>`,
          )
          .join("")}
        <button type="button" id="add-sensor">+ powered sensor</button>
        <p class="hm-hint">ALM rail budget 150 mA per module — the estimate warns if sensor current exceeds it.</p>
      </div>`;
    container.querySelectorAll(".hm-sensor-row").forEach((row) => {
      const i = Number(row.dataset.si);
      row.querySelectorAll("[data-sk]").forEach((inp) => {
        inp.onchange = inp.oninput = () => {
          const k = inp.dataset.sk;
          if (k === "type") state.systems.security.powered_sensors[i].type = inp.value;
          else state.systems.security.powered_sensors[i].qty = Number(inp.value) || 0;
          saveState();
          bump();
        };
      });
      row.querySelector("[data-srm]").onclick = () => {
        state.systems.security.powered_sensors.splice(i, 1);
        saveState();
        renderPoweredSensors(container);
        bump();
      };
    });
    container.querySelector("#add-sensor").onclick = () => {
      const first = Object.keys(types)[0] || "pir";
      state.systems.security.powered_sensors.push({ type: first, qty: 1 });
      saveState();
      renderPoweredSensors(container);
      bump();
    };
  }

  function renderEngineering() {
    const sys = state.systems;
    const sectionsHtml = SYSTEM_SECTIONS.map((sec) => {
      const secPanel = sys[sec.id]?.panel_id || firstPanelId();
      const fields = sec.fields
        .map(([key, label, kind]) => {
          if (kind === "powered_sensors") {
            return `<div class="hm-sys-field"><span>${label}</span><div data-powered-host></div></div>`;
          }
          const tip =
            sec.id === "heating" && key === "collector_loops"
              ? `<button type="button" class="hm-field-tip" title="Compared with the sum of per-room underfloor loops; the engine uses the maximum, not the sum." aria-label="Help">?</button>`
              : "";
          return `<div class="hm-room-field">
            <div class="hm-room-field__label"><span>${escapeAttr(label)}</span>${tip}</div>
            ${sysFieldControl(sec.id, key, kind, sys[sec.id]?.[key])}
          </div>`;
        })
        .join("");
      return `<details class="hm-sys-section" open>
        <summary>${sec.title}</summary>
        <div class="hm-room-field hm-sys-panel-pick">
          <div class="hm-room-field__label"><span>Panel</span></div>
          ${panelSelectHtml(secPanel, `data-sys-panel="${sec.id}"`)}
        </div>
        <div class="hm-sys-grid">${fields}</div>
      </details>`;
    }).join("");

    main.innerHTML = `
      <h2>Systems</h2>
      <p class="hm-muted">Describe equipment — the engine converts it to channel demand. Each section is assigned to a panel. You never enter channel counts here.</p>
      ${sectionsHtml}
      <div class="hm-actions">
        <button type="button" id="hm-back">Back</button>
        <button type="button" id="hm-next">To result</button>
      </div>
    `;

    const poweredHost = main.querySelector("[data-powered-host]");
    if (poweredHost) renderPoweredSensors(poweredHost);

    main.querySelectorAll("[data-sys-panel]").forEach((sel) => {
      sel.onchange = () => {
        const sec = sel.dataset.sysPanel;
        state.systems[sec].panel_id = sel.value;
        saveState();
        bump();
      };
    });

    main.querySelectorAll("[data-sys]").forEach((inp) => {
      const apply = () => {
        const [sec, key] = inp.dataset.sys.split(".");
        if (key === "boiler") {
          state.systems.heating.boiler = inp.value;
        } else {
          state.systems[sec][key] = Number(inp.value) || 0;
        }
        saveState();
        bump();
      };
      inp.onchange = apply;
      inp.oninput = apply;
    });

    main.querySelector("#hm-back").onclick = () => {
      state.step = 1;
      saveState();
      render();
    };
    main.querySelector("#hm-next").onclick = () => {
      state.step = 3;
      saveState();
      render();
    };
  }

  function renderExpert() {
    main.innerHTML = `
      <h2>Expert demand (JSON)</h2>
      <textarea id="expert-json" rows="16">${JSON.stringify(state.expertDemand, null, 2)}</textarea>
      <div class="hm-actions">
        <button type="button" id="hm-apply">Apply</button>
        <button type="button" id="hm-next">To result</button>
      </div>
    `;
    main.querySelector("#hm-apply").onclick = () => {
      try {
        state.expertDemand = JSON.parse(main.querySelector("#expert-json").value || "{}");
        saveState();
        bump();
      } catch (e) {
        alert("JSON: " + e.message);
      }
    };
    main.querySelector("#hm-next").onclick = () => {
      state.step = 3;
      saveState();
      render();
    };
  }

  function panelResultBlock(panel) {
    const ctrl = (panel.modules || []).filter((m) => rules.modules?.[m.id]?.master);
    const slaves = (panel.modules || []).filter((m) => !rules.modules?.[m.id]?.master);
    const modRows = [...ctrl, ...slaves]
      .map((m) => {
        const p = priceMap[m.sku];
        const priceCell =
          p && typeof p.amount === "number" ? `${p.amount} ${p.currency || ""}` : "—";
        const din = m.din_units != null ? `${m.din_units} M` : "—";
        return `<tr>
          <td>${m.qty}×</td>
          <td><a href="${m.shop_url || "#"}">${m.id}</a></td>
          <td>${m.sku || ""}</td>
          <td>${din}</td>
          <td>${priceCell}</td>
        </tr>`;
      })
      .join("");
    const companions = (panel.accessories || [])
      .map((a) => {
        const din = a.din_units != null ? `${a.din_units} M` : "—";
        return `<tr>
          <td>${a.qty}×</td>
          <td>${escapeAttr(a.label || a.id)}</td>
          <td class="hm-muted">requirement</td>
          <td>${din}</td>
          <td></td>
        </tr>`;
      })
      .join("");
    const segs = panel.topology?.segments?.length ?? 0;
    const terms = (panel.topology?.segments || []).reduce(
      (s, seg) => s + (seg.terminators || 0),
      0,
    );
    const psu = (panel.power?.requirements || [])
      .filter((r) => r.kind === "psu" || /PSU|power supply/i.test(r.text || ""))
      .map((r) => r.text || JSON.stringify(r))
      .join("; ");
    const loc = panel.location ? ` · ${escapeAttr(panel.location)}` : "";
    const yaml = (panel.topology?.esphome_yaml || "").replace(/</g, "&lt;");
    const ctrlCount = ctrl.reduce((s, m) => s + (m.qty || 0), 0);
    const roomLine = (panel.rooms || []).length
      ? `Rooms: ${panel.rooms.map(escapeAttr).join(", ")}`
      : "Rooms: —";
    const sysLine = (panel.systems || []).length
      ? `Systems: ${panel.systems.map(escapeAttr).join(", ")}`
      : "Systems: —";
    const occ = panel.occupied ?? panel.din_occupied ?? panel.enclosure?.occupied ?? panel.enclosure?.din_occupied;
    const res = panel.reserve ?? panel.din_reserve ?? panel.enclosure?.reserve ?? panel.enclosure?.din_reserve;
    const free = panel.free ?? panel.din_free ?? panel.enclosure?.free ?? panel.enclosure?.din_free;
    const reserveLine =
      occ != null && res != null && free != null
        ? `<p class="hm-muted">DIN: occupied ${occ} M · reserve ${res} M · free after rounding ${free} M · capacity ${panel.capacity ?? panel.enclosure?.capacity ?? "—"} M</p>`
        : "";
    return `
      <section class="hm-panel-result">
        <h3>${escapeAttr(panel.name)}${loc}</h3>
        <p class="hm-muted">${roomLine} · ${sysLine}</p>
        ${reserveLine}
        <p class="hm-muted">RS-485: ${segs} segment(s), ${ctrlCount} controller(s), ${terms} terminator(s) · 24 V: ${panel.power?.total_w ?? "—"} W${psu ? ` · ${escapeAttr(psu)}` : ""}</p>
        ${enclosureMessage(panel.enclosure)}
        <table class="hm-table"><thead><tr><th>Qty</th><th>Item</th><th>SKU / note</th><th>Width</th><th>Price incl. VAT</th></tr></thead>
        <tbody>${modRows}${companions}</tbody></table>
        ${channelUsageTable(panel.channel_usage)}
        <details><summary>ESPHome YAML</summary><pre>${yaml}</pre></details>
      </section>`;
  }

  async function renderResult() {
    let result = liveResult();
    main.innerHTML = `<p>Loading prices from the shop…</p>`;
    await refreshPrices(result);
    result = liveResult();
    renderSummary(result);

    const panelBlocks = (result.panels || [])
      .map((p) => panelResultBlock(p))
      .join("");

    const almWarn = (result.assumptions || [])
      .filter((a) => /ALM 12 V rail:.*exceeds/i.test(a))
      .map((a) => `<p class="${/exceeds/i.test(a) ? "hm-warn" : "hm-muted"}">${escapeAttr(a)}</p>`)
      .join("");
    const split = result.split_warning
      ? `<p class="hm-warn">${escapeAttr(result.split_warning)}</p>`
      : "";
    const tot = cartTotal(result, priceMap);
    let totalLine = "";
    if (tot && typeof tot.total === "number") {
      totalLine = `<p class="hm-total">Project total (HomeMaster): ${tot.total} ${tot.currency} (incl. VAT)</p>`;
    }

    main.innerHTML = `
      <h2>Result</h2>
      ${split}
      ${almWarn}
      ${panelBlocks || "<p>No panels.</p>"}
      <h3>Project total</h3>
      ${channelUsageTable(result.channel_usage)}
      ${enclosureMessage(result.enclosure, { compact: true })}
      ${totalLine}
      <div class="hm-actions">
        <button type="button" id="hm-cart">Add to cart</button>
        <button type="button" id="hm-xlsx">Download .xlsx</button>
        <button type="button" id="hm-csv">CSV</button>
        <button type="button" id="hm-back">Back</button>
      </div>
      <div id="hm-cart-status"></div>
    `;

    main.querySelector("#hm-xlsx").onclick = () =>
      downloadXlsx(result).catch(() => downloadCsv(result));
    main.querySelector("#hm-csv").onclick = () => downloadCsv(result);
    main.querySelector("#hm-back").onclick = () => {
      state.step = state.expert ? 0 : 2;
      saveState();
      render();
    };
    main.querySelector("#hm-cart").onclick = async () => {
      const status = main.querySelector("#hm-cart-status");
      status.textContent = "Adding…";
      const { added, failed } = await addAllToCart(result.cart_lines || []);
      if (failed) {
        status.innerHTML = `
          <p class="hm-warn">Added ${added.length} item(s); failed on ${failed.line?.sku}: ${failed.error}</p>
          <p><a href="/shop/cart">Open cart</a> · you can still download the estimate</p>`;
        return;
      }
      status.innerHTML = `<p>Done: ${added.length} item(s). <a href="/shop/cart">Go to cart</a></p>`;
    };
  }

  function bump() {
    if (state.ui_mode === "simple") return;
    renderSummary(liveResult());
  }

  function sliderRow(id, label, value, min, max, icon) {
    return `<div class="hm-slider">
      <div class="hm-slider__label">
        <span class="hm-slider__name">${icon ? hmIcon(icon, 16) : ""}<span>${escapeAttr(label)}</span></span>
        <strong id="${id}-val">${value}</strong>
      </div>
      <input type="range" id="${id}" min="${min}" max="${max}" value="${value}">
    </div>`;
  }

  function sectionTitle(icon, title) {
    return `<h3 class="hm-simple-sec__title">${hmIcon(icon, 18)}<span>${escapeAttr(title)}</span></h3>`;
  }

  function renderSimple() {
    summary.innerHTML = "";
    const c = state.simple.counts;
    const t = state.simple.totals;
    const g = state.simple.toggles;
    const warn = (state.simple.warnings || [])
      .map((w) => `<p class="hm-warn">${escapeAttr(w)}</p>`)
      .join("");

    const roomIcons = {
      bedroom: "bed",
      bath: "bath",
      living: "living",
      kitchen: "kitchen",
      hallway: "hall",
      office: "office",
      garage: "garage",
      boiler_room: "utility",
    };
    const roomSliders = SIMPLE_ROOM_TYPES.map(({ id, label }) =>
      sliderRow(`sc-${id}`, label, c[id] ?? 0, 0, 10, roomIcons[id]),
    ).join("");

    const equip = [
      ["lights_onoff", "Light groups", 40, "light"],
      ["lights_dimmable", "of which dimmable", 40, "dim"],
      ["led_strips", "RGB strips", 20, "rgb"],
      ["switches", "Wall switches", 60, "switch"],
      ["shutters", "Blinds / shutters", 30, "shutter"],
      ["ufh_loops", "Underfloor heating loops", 40, "heat"],
      ["leak_sensors", "Leak sensors", 20, "leak"],
      ["motion_sensors", "Motion detectors", 30, "motion"],
      ["door_contacts", "Door contacts", 40, "door"],
      ["smart_sockets", "Sockets", 30, "socket"],
    ]
      .map(([id, label, max, icon]) => sliderRow(`st-${id}`, label, t[id] ?? 0, 0, max, icon))
      .join("");

    main.innerHTML = `
      <div class="hm-simple">
        <div class="hm-simple__settings">
          <div class="hm-simple-sec hm-simple-sec--top">
            <label class="hm-simple__ptype">Property type
              <select id="s-ptype">${PROPERTY_TYPES.map(
                ([v, lab]) =>
                  `<option value="${v}" ${v === state.object.property_type ? "selected" : ""}>${lab}</option>`,
              ).join("")}</select>
            </label>
            <button type="button" id="s-defaults" class="hm-btn-secondary">${hmIcon("spark", 16)} Use default configuration</button>
          </div>

          <section class="hm-simple-sec">
            ${sectionTitle("rooms", "Rooms")}
            <div class="hm-slider-grid">${roomSliders}</div>
          </section>

          <section class="hm-simple-sec">
            ${sectionTitle("gear", "Equipment")}
            <div class="hm-slider-stack">${equip}</div>
          </section>

          <section class="hm-simple-sec">
            ${sectionTitle("estimate", "Whole-home systems")}
            <div class="hm-simple-toggles">
              <label class="hm-simple-toggle">
                <span class="hm-simple-toggle__lab">${hmIcon("boiler", 16)} Boiler</span>
                <select id="s-boiler">
                  <option value="none" ${g.boiler === "none" ? "selected" : ""}>None</option>
                  <option value="opentherm" ${g.boiler === "opentherm" ? "selected" : ""}>OpenTherm</option>
                  <option value="relay" ${g.boiler === "relay" ? "selected" : ""}>Relay</option>
                </select>
              </label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-vent" ${g.ventilation ? "checked" : ""}>${hmIcon("vent", 16)} Ventilation</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-energy" ${g.energy_metering ? "checked" : ""}>${hmIcon("energy", 16)} Energy metering</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-sec" ${g.security ? "checked" : ""}>${hmIcon("security", 16)} Security</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-water" ${g.garden_watering ? "checked" : ""}>${hmIcon("water", 16)} Garden watering</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-gates" ${g.gates ? "checked" : ""}>${hmIcon("gate", 16)} Gates</label>
            </div>
          </section>
          ${warn}
        </div>
        <div class="hm-simple__result" id="hm-simple-result">
          <p class="hm-muted">Calculating…</p>
        </div>
      </div>`;

    const bindRange = (id, apply) => {
      const input = main.querySelector(`#${id}`);
      const val = main.querySelector(`#${id}-val`);
      if (!input) return;
      input.oninput = () => {
        const n = Number(input.value) || 0;
        if (val) val.textContent = String(n);
        apply(n);
        runSimpleSync();
        saveState();
        paintSimpleResult();
      };
    };

    for (const { id } of SIMPLE_ROOM_TYPES) {
      bindRange(`sc-${id}`, (n) => {
        state.simple.counts[id] = n;
      });
    }
    for (const field of SIMPLE_DISTRIBUTE_FIELDS) {
      bindRange(`st-${field}`, (n) => {
        state.simple.totals[field] = n;
        if (field === "lights_dimmable") {
          const lights = Number(state.simple.totals.lights_onoff) || 0;
          if (n > lights) {
            state.simple.totals.lights_dimmable = lights;
            const inp = main.querySelector("#st-lights_dimmable");
            const v = main.querySelector("#st-lights_dimmable-val");
            if (inp) inp.value = String(lights);
            if (v) v.textContent = String(lights);
          }
        }
      });
    }

    main.querySelector("#s-ptype").onchange = (e) => {
      state.object.property_type = e.target.value;
      saveState();
    };
    main.querySelector("#s-defaults").onclick = () => {
      const kind =
        state.object.property_type === "house" || state.object.property_type === "townhouse"
          ? "house"
          : state.object.property_type === "commercial"
            ? "apartment"
            : "apartment";
      applyPreset(kind);
      saveState();
      render();
    };
    main.querySelector("#s-boiler").onchange = (e) => {
      state.simple.toggles.boiler = e.target.value;
      runSimpleSync();
      saveState();
      paintSimpleResult();
    };
    for (const [id, key] of [
      ["s-vent", "ventilation"],
      ["s-energy", "energy_metering"],
      ["s-sec", "security"],
      ["s-water", "garden_watering"],
      ["s-gates", "gates"],
    ]) {
      main.querySelector(`#${id}`).onchange = (e) => {
        state.simple.toggles[key] = e.target.checked;
        runSimpleSync();
        saveState();
        paintSimpleResult();
      };
    }

    paintSimpleResult();
  }

  async function paintSimpleResult() {
    const host = main.querySelector("#hm-simple-result");
    if (!host) return;
    let result = liveResult();
    await refreshPrices(result);
    result = liveResult();
    const tot = cartTotal(result, priceMap);
    const lines = simpleCustomerSummary(
      state.simple.totals,
      state.simple.toggles,
      state.systems,
    );
    const list = lines
      .map(
        (l) =>
          `<li><span class="hm-simple-line__ico">${hmIcon(l.kind, 18)}</span><span>${escapeAttr(l.text)}</span></li>`,
      )
      .join("");
    let priceHtml = `<p class="hm-simple-price">—</p>`;
    if (tot && typeof tot.total === "number") {
      priceHtml = `<p class="hm-simple-price">${tot.total} <span>${escapeAttr(tot.currency)}</span></p>`;
    }
    const warn = (state.simple.warnings || [])
      .map((w) => `<p class="hm-warn">${escapeAttr(w)}</p>`)
      .join("");
    host.innerHTML = `
      <div class="hm-simple-result__head">
        ${hmIcon("estimate", 20)}
        <h2>Your estimate</h2>
      </div>
      ${priceHtml}
      <p class="hm-muted">Equipment only, excluding installation. Prices incl. VAT, as shown in the shop.</p>
      <ul class="hm-simple-lines">${list || "<li class='hm-muted'>Adjust the sliders to build your system.</li>"}</ul>
      ${warn}
      <div class="hm-actions">
        <button type="button" id="s-fullspec">Show full specification</button>
        <button type="button" id="s-cart">Add to cart</button>
      </div>
      <div id="s-cart-status"></div>`;
    host.querySelector("#s-fullspec").onclick = () => setUiMode("advanced");
    host.querySelector("#s-cart").onclick = async () => {
      const status = host.querySelector("#s-cart-status");
      status.textContent = "Adding…";
      const { added, failed } = await addAllToCart(result.cart_lines || []);
      if (failed) {
        status.innerHTML = `<p class="hm-warn">Added ${added.length}; failed on ${failed.line?.sku}</p>`;
        return;
      }
      status.innerHTML = `<p>Done: ${added.length} item(s). <a href="/shop/cart">Go to cart</a></p>`;
    };
  }

  function render() {
    renderModeChrome();
    renderExamples();
    renderSteps();
    if (state.ui_mode === "simple") {
      if (!state.rooms?.length) runSimpleSync();
      renderSimple();
      return;
    }
    if (state.expert && state.step > 0 && state.step < 3) {
      renderExpert();
      bump();
      return;
    }
    if (state.step === 0) renderObject();
    else if (state.step === 1) renderRooms();
    else if (state.step === 2) renderEngineering();
    else renderResult();
    if (state.step !== 3) bump();
  }

  render();
}

function findRoot() {
  if (typeof document === "undefined") return null;
  return (
    document.getElementById("hm-configurator") ||
    document.getElementById("hm-system-builder") ||
    document.querySelector("[data-hm-estimator]")
  );
}

async function init() {
  ensureStylesheet();
  await loadRules();
  loadState();
  ensureRoomsSeeded();
  const root = findRoot();
  if (root) mountConfigurator(root);
  else console.error("HM estimator: mount node not found (#hm-configurator / #hm-system-builder)");
}

function ensureStylesheet() {
  if (typeof document === "undefined") return;
  const href = "https://config.home-master.eu/estimator/app.css";
  if (
    [...document.querySelectorAll("link[rel='stylesheet']")].some((l) =>
      l.href.includes("/estimator/app.css"),
    )
  ) {
    return;
  }
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = href;
  document.head.appendChild(link);
}

function boot() {
  init().catch((err) => {
    const root = findRoot();
    if (root) {
      root.innerHTML = `<p class="hm-warn">Estimator failed: ${err?.message || err}</p>`;
    }
    console.error(err);
  });
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot, { once: true });
  } else {
    boot();
  }
}

HM.loadRules = loadRules;
HM.seedRoomsFromProperty = seedRoomsFromProperty;
HM.runEstimate = runEstimate;
HM.mountConfigurator = mountConfigurator;
HM.init = init;


export { estimate, loadRules, runEstimate, mountConfigurator, init, fetchPrice, fetchPrices, addAllToCart, downloadXlsx };
